from openpyxl import load_workbook
from pathlib import Path
p=Path('/root/output/result.xlsx')
print('result exists', p.exists(), 'size', p.stat().st_size if p.exists() else None)
wb=load_workbook(p, data_only=False)
ws=wb['Task']
checks = []
# specified lookup samples
checks += ['H12','L17','H19','L24','H26','L31']
# buffer samples
checks += ['H35','L40']
# summary full H42:L47
for r in range(42,48):
    for c in range(8,13):
        checks.append(ws.cell(r,c).coordinate)
# weighted mean H50:L50
for c in range(8,13):
    checks.append(ws.cell(50,c).coordinate)
missing=[]
for coord in checks:
    v=ws[coord].value
    if not (isinstance(v, str) and v.startswith('=')):
        missing.append((coord, v))
print('checked formula cells', len(checks))
print('missing/non-formula count', len(missing))
if missing:
    print('MISSING/NON-FORMULA:')
    for coord, v in missing:
        print(coord, repr(v))
else:
    print('all checked cells contain formula strings')
print('\nFormula samples:')
for coord in ['H12','L17','H19','L24','H26','L31','H35','L40','H42','I43','J44','K45','L46','L47','H50','L50']:
    print(coord, ws[coord].value)

# Also confirm every requested formula block is filled with formulas.
block_ranges=[]
for rows in [(12,17),(19,24),(26,31),(35,40),(42,47)]:
    for r in range(rows[0], rows[1]+1):
        for c in range(8,13):
            block_ranges.append(ws.cell(r,c).coordinate)
for c in range(8,13):
    block_ranges.append(ws.cell(50,c).coordinate)
not_formula=[(coord,ws[coord].value) for coord in block_ranges if not (isinstance(ws[coord].value,str) and ws[coord].value.startswith('='))]
print('\nall target block formula cells', len(block_ranges), 'non-formula', len(not_formula))
if not_formula:
    for item in not_formula[:20]: print(item)
    raise SystemExit(1)
